            { id: 'd2', notes: [{ body: 'r2' }] },
            { id: 'd3', notes: [{ body: 'r3' }] }
        ];
        var out = makeGitlab(d).fetchDiscussions(7);
        assert.deepEqual(out.rawThreads.threads.map(function (t) { return [t.index, t.rootCommentId]; }),
            [[1, 'd1'], [2, 'd2'], [3, 'd3']]);
