{"content":"/* Scratch verification (rework pass 2): byte-equality of fetchDiscussions output
 * between origin/main (pre-refactor) and this branch (post-refactor), re-proving
 * the review's BLOCKING fix. Loads BOTH scm.js copies with identical mocked
 * inputs over a comprehensive matrix and asserts markdown === + rawThreads deep-
 * equal. NOT part of the suite — scratch file, deleted after the run. */
/* global loadModule, assert, test, suite, makeRequire */

suite('rework bytecheck', function () {

    function loadScm(path, mocks) {
        return loadModule(path,
            makeRequire({ './machineNotice.js': loadModule('js/common/machineNotice.js') }),
            mocks || {});
    }

    // ── GitLab input matrix ────────────────────────────────────────────────
    var GL_CASES = [
        ['empty list', []],
        ['value envelope empty', { value: [] }],
        ['null result', null],
        ['all resolved', [
            { id: 'd1', resolved: true, notes: [{ body: 'r1', author: { username: 'a' }, created_at: '2026-01-01T00:00:00Z' }] },
            { id: 'd2', notes: [{ body: 'r2', resolved: true }] }
        ]],
        ['mixed: replies, no-notes, whitespace body, empty author object, old fallback', [
            { id: 'd1', resolved: true, notes: [{ body: 'resolved one' }] },
            { id: 'd2', notes: [
                { body: '  please fix  ', position: { new_path: '/src/a.js', new_line: 12 },
                  author: { username: 'dev1' }, created_at: '2026-02-03T11:00:00Z' },
                { body: ' on it ', author: { name: 'Second Dev' }, created_at: '2026-02-04T09:30:00Z' },
                { body: '', author: undefined, created_at: undefined }
            ]},
            { id: 'd3', notes: [] },
            { id: 'd4' },
            { id: 'd5', notes: [{ body: '   ' }] },
            { id: 'd6', notes: [{ body: 'old-style', position: { old_path: '/old.js', old_line: 3 } }] },
            { id: 'd7', notes: [{ body: 'no author at all' }] },
            { id: 'd8', notes: [{ body: 'empty author obj', author: {} }] }
        ]],
        ['bare array passthrough', [
            { id: 'd1', notes: [{ body: 'x', author: { username: 'u' }, created_at: '2026-05-06T00:00:00Z', position: { new_path: '/b.js', new_line: 4 } }] }
        ]],
        ['line without path', [
            { id: 'd1', notes: [{ body: 'orphan line', position: { new_line: 9 }, author: { username: 'u' } }] }
        ]]
    ];

    GL_CASES.forEach(function (c) {
        test('gitlab fetchDiscussions byte-equality: ' + c[0], function () {
            var newMod = loadScm('js/common/scm.js',
                { gitlab_get_mr_discussions: function () { return c[1]; } });
            var oldMod = loadScm('js/common/scm_main_scratch.js',
                { gitlab_get_mr_discussions: function () { return c[1]; } });
            var n = newMod._createGitLabProvider('mygroup', 'my-repo').fetchDiscussions(7);
            var o = oldMod._createGitLabProvider('mygroup', 'my-repo').fetchDiscussions(7);
            assert.equal(n.markdown, o.markdown);
            assert.deepEqual(n.rawThreads, o.rawThreads);
        });
    });

    // ── ADO input matrix ───────────────────────────────────────────────────
    function adoThread(id, status, opts) {
        opts = opts || {};
        return {
            id: id,
            status: status,
            isDeleted: opts.isDeleted === true,
            threadContext: opts.threadContext,
            comments: opts.comments
        };
    }
    function adoComment(content, author, publishedDate) {
        var c = { content: content };
        if (author) c.author = { displayName: author };
        if (publishedDate) c.publishedDate = publishedDate;
        return c;
    }
    var ADO_CASES = [
        ['empty value', JSON.stringify({ value: [] })],
        ['bare array (java-list)', JSON.stringify([adoThread(1, 'active', { comments: [adoComment('x')] })])],
        ['bare object', JSON.stringify({ count: 0 })],
        ['null', null],
        ['garbage string', 'not json'],
        ['mixed statuses and contexts', JSON.stringify({ value: [
            adoThread(1, 'active', { threadContext: { filePath: '/a.js', rightFileStart: { line: 4 } }, comments: [
                adoComment('first', 'Alice', '2026-01-02T10:00:00Z'),
                adoComment('second reply', 'Bob', '2026-01-03T11:00:00Z')
            ]}),
            adoThread(2, 'resolved', { comments: [adoComment('done', 'Carol')] }),
            adoThread(3, 'closed', { comments: [adoComment('closed one')] }),
            adoThread(4, 'unknownStatus', { comments: [adoComment('odd status')] }),
            adoThread(5, 'active', { isDeleted: true, comments: [adoComment('deleted')] }),
            adoThread(6, 'active', { threadContext: { filePath: '/b.js', leftFileStart: { line: 9 } }, comments: [adoComment('left side')] }),
            adoThread(7, 'active', { comments: [] }),
            adoThread(8, 'active'),
            adoThread(9, 'active', { comments: [adoComment('   '), adoComment(null), adoComment('tail')] })
        ]})]
    ];

    ADO_CASES.forEach(function (c) {
        test('ado fetchDiscussions byte-equality: ' + c[0], function () {
            var newMod = loadScm('js/common/scm.js',
                { ado_get_pr_comments: function () { return c[1]; } });
            var oldMod = loadScm('js/common/scm_main_scratch.js',
                { ado_get_pr_comments: function () { return c[1]; } });
            var n = newMod._createAdoProvider('my-repo').fetchDiscussions(5);
            var o = oldMod._createAdoProvider('my-repo').fetchDiscussions(5);
            assert.equal(n.markdown, o.markdown);
            assert.deepEqual(n.rawThreads, o.rawThreads);
        });
    });

    // ── The exact setext-H2 scenario from the review comment ───────────────
    test('gitlab placeholder thread renders blank line before --- rule (setext guard)', function () {
        var newMod = loadScm('js/common/scm.js',
            { gitlab_get_mr_discussions: function () { return [{ id: 'd1' }]; } });
        var out = newMod._createGitLabProvider('mygroup', 'my-repo').fetchDiscussions(7);
        assert.contains(out.markdown, '### Thread 1\n\n_[No comment body]_\n\n---\n\n');
        // the drifted (buggy) shape must NOT be producible
        assert.notContains(out.markdown, '_[No comment body]_\n---');
    });
});
